import math


def _finite_number(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError(f"{name} must be numeric")
    value = float(value)
    if not math.isfinite(value):
        raise ValueError(f"{name} must be finite")
    return value


def plan_rescue(start, sensor_batches, *, threshold=100.0):
    if not isinstance(start, bool):
        raise TypeError("start must be a boolean")
    if not isinstance(sensor_batches, list):
        raise TypeError("sensor_batches must be a list")
    threshold = _finite_number(threshold, "threshold")
    if threshold <= 0:
        raise ValueError("threshold must be positive")

    batches = []
    for batch in sensor_batches:
        if not isinstance(batch, list):
            raise TypeError("each batch must be a list")
        if not batch:
            raise ValueError("sensor batches cannot be empty")
        values = [_finite_number(value, "reading") for value in batch]
        if any(value < 0 for value in values):
            raise ValueError("readings cannot be negative")
        batches.append(tuple(values))

    if not start:
        return []

    actions = []
    for index, batch in enumerate(batches):
        peak = max(batch)
        if peak >= threshold:
            middle = len(batch) // 2
            left = batch[:middle]
            right = batch[middle:]
            left_mean = sum(left) / len(left) if left else 0.0
            right_mean = sum(right) / len(right) if right else 0.0
            denominator = abs(left_mean) + abs(right_mean)
            turn = (right_mean - left_mean) / denominator if denominator else 0.0
            actions.append(("TURN", round(turn, 6)))
            actions.append(("APPROACH", peak))
            actions.append(("EXTINGUISH",))
            break
        actions.append(("SEARCH", index))
    return actions

